import os, json, hashlib, stat
for path in paths:
    row = {'path': path}
    try:
        st = os.stat(path)
        row['exists'] = True
        if stat.S_ISREG(st.st_mode):
            row.update(kind='file', bytes=st.st_size)
            h = hashlib.sha256()
            with open(path, 'rb') as f:
                for block in iter(lambda: f.read(1048576), b''): h.update(block)
            row['sha256'] = h.hexdigest()
        elif stat.S_ISDIR(st.st_mode):
            total = 0; count = 0; errors = []
            def onerror(e): errors.append(str(e))
            for base, dirs, files in os.walk(path, followlinks=False, onerror=onerror):
                for name in files:
                    try:
                        s = os.stat(os.path.join(base, name))
                        if stat.S_ISREG(s.st_mode): total += s.st_size; count += 1
                    except OSError as e: errors.append(str(e))
            row.update(kind='directory', bytes=total, file_count=count, traversal_errors=errors)
        else: row.update(kind='other', bytes=st.st_size)
    except OSError as e:
        row.update(exists=False if isinstance(e, FileNotFoundError) else None, error_type=type(e).__name__, errno=e.errno)
    print(json.dumps(row, separators=(',', ':')))

